PRAGMA foreign_keys=ON;
CREATE TABLE connections(id TEXT PRIMARY KEY,import_id TEXT,import_status TEXT CHECK(import_status IN ('pending','running','succeeded','failed')),import_admitted_at TEXT,import_sequence INTEGER NOT NULL DEFAULT 0 CHECK(import_sequence>=0),import_checkpoint TEXT CHECK(import_checkpoint IS NULL OR json_valid(import_checkpoint)),import_error TEXT,last_success_at TEXT);
CREATE TRIGGER connection_limit BEFORE INSERT ON connections WHEN (SELECT count(*) FROM connections)>=10 AND NOT EXISTS(SELECT 1 FROM connections WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'ITEM_LIMIT'); END;
CREATE TABLE accounts(connection_id TEXT NOT NULL REFERENCES connections(id),id TEXT NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('BANK','CREDIT')),currency TEXT NOT NULL,balance_minor TEXT,source_updated_at TEXT,observed_at TEXT NOT NULL,last_seen_run TEXT NOT NULL,collection_status TEXT NOT NULL DEFAULT 'never',last_attempt_at TEXT,last_success_at TEXT,last_completed_from TEXT,last_completed_to TEXT,observed_from TEXT,observed_to TEXT,error TEXT,PRIMARY KEY(connection_id,id));
CREATE TABLE transactions(connection_id TEXT NOT NULL,account_id TEXT NOT NULL,id TEXT NOT NULL,date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('PENDING','POSTED')),direction TEXT NOT NULL CHECK(direction IN ('DEBIT','CREDIT')),currency TEXT NOT NULL,amount_minor TEXT,description TEXT NOT NULL,category TEXT,PRIMARY KEY(connection_id,account_id,id),FOREIGN KEY(connection_id,account_id) REFERENCES accounts(connection_id,id));
CREATE INDEX transaction_date ON transactions(date,connection_id,account_id,id);
CREATE INDEX transaction_account ON transactions(connection_id,account_id,date,id);
CREATE INDEX transaction_status ON transactions(status,date);
CREATE INDEX transaction_category ON transactions(category);
